class Solution:
    def climbStairsII(self, n: int, costs: list[int]) -> int:
        INF = float('inf')
        dp = [INF] * (n + 1)
        dp[0] = 0
        for i in range(1, n + 1):
            for d in (1, 2, 3):
                if i >= d and dp[i - d] < INF:
                    v = dp[i - d] + costs[i - 1] + d * d
                    if v < dp[i]:
                        dp[i] = v
        return dp[n]

