class Solution {
public:
    int climbStairsII(int n, vector<int>& costs) {
        const long long INF = LLONG_MAX / 4;
        vector<long long> dp(n + 1, INF);
        dp[0] = 0;
        for (int i = 1; i <= n; i++)
            for (int d = 1; d <= 3 && i >= d; d++)
                dp[i] = min(dp[i], dp[i - d] + costs[i - 1] + (long long)d * d);
        return (int)dp[n];
    }
};

