class Solution {
    public int climbStairsII(int n, int[] costs) {
        long INF = Long.MAX_VALUE / 4;
        long[] dp = new long[n + 1];
        java.util.Arrays.fill(dp, INF);
        dp[0] = 0;
        for (int i = 1; i <= n; i++)
            for (int d = 1; d <= 3 && i >= d; d++)
                dp[i] = Math.min(dp[i], dp[i - d] + costs[i - 1] + (long) d * d);
        return (int) dp[n];
    }
}

