var climbStairsII = function(n, costs) {
    const INF = Infinity;
    const dp = new Array(n + 1).fill(INF);
    dp[0] = 0;
    for (let i = 1; i <= n; i++)
        for (let d = 1; d <= 3 && i >= d; d++)
            dp[i] = Math.min(dp[i], dp[i - d] + costs[i - 1] + d * d);
    return dp[n];
};
